// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type StepsAnimationProps = Record<string, any>;

const StepsAnimation: React.FC<StepsAnimationProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  mainTitle = "3 Simple Steps",
  mainTitleColor = "#ffffff",
  boxColor = "rgba(255, 255, 255, 0.05)",
  boxBorderColor = "rgba(255, 255, 255, 0.15)",
  textColor = "#e0e0e0",
  accentColor = "#00f0ff",
  glassBlurAmount = 24,
  contentInitialBlur = 20,
  steps = [
    {
      title: "Initiation",
      description: "Define the core objectives and outline the project scope.",
    },
    {
      title: "Execution",
      description: "Develop and iterate on the fundamental architecture.",
    },
    {
      title: "Completion",
      description: "Finalize details and deploy the solution to production.",
    },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Ensure we don't break if user provides more or less than 3 steps, 
  // but slice to 3 based on the prompt's context
  const displaySteps = steps.slice(0, 3);

  // Main Title Animation
  const titleOpacity = interpolate(frame, [0, 25], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 25], [50, 0], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: `${height * 0.15}px 0 ${height * 0.1}px 0`, // Safe zones
      }}
    >
      {/* Main Title */}
      <div
        style={{
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
          marginBottom: "80px",
          textAlign: "center",
          transition: "none",
        }}
      >
        <h1
          style={{
            color: mainTitleColor,
            fontSize: "80px",
            fontWeight: 800,
            margin: 0,
            letterSpacing: "-0.02em",
          }}
        >
          {mainTitle}
        </h1>
      </div>

      {/* Steps Container */}
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          gap: "40px",
          width: "85%",
          maxWidth: "900px",
        }}
      >
        {displaySteps.map((step, index) => {
          // Stagger calculations
          const startFrame = 15 + index * 20;

          // Box entrance physics
          const boxProgress = spring({
            frame: frame - startFrame,
            fps,
            config: { damping: 14, mass: 0.8 },
          });

          const boxOpacity = interpolate(
            frame,
            [startFrame, startFrame + 15],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const boxY = interpolate(boxProgress, [0, 1], [150, 0]);

          // Content blur effect - comes into focus
          const contentBlur = interpolate(
            frame,
            [startFrame + 10, startFrame + 35],
            [contentInitialBlur, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const contentOpacity = interpolate(
            frame,
            [startFrame + 10, startFrame + 30],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Number spring animation
          const numberScale = spring({
            frame: frame - (startFrame + 15),
            fps,
            config: { stiffness: 150, damping: 10, overshootClamping: false },
          });

          return (
            <div
              key={index}
              style={{
                opacity: boxOpacity,
                transform: `translateY(${boxY}px)`,
                backgroundColor: boxColor,
                backdropFilter: `blur(${glassBlurAmount}px)`,
                WebkitBackdropFilter: `blur(${glassBlurAmount}px)`,
                border: `1px solid ${boxBorderColor}`,
                borderRadius: "32px",
                padding: "48px",
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                gap: "40px",
                transition: "none",
                boxShadow: "0 20px 40px rgba(0,0,0,0.2)",
              }}
            >
              {/* Animated Number */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  minWidth: "140px",
                  height: "140px",
                  borderRadius: "50%",
                  backgroundColor: `${accentColor}1A`, // 10% opacity accent
                  border: `2px solid ${accentColor}`,
                  transform: `scale(${numberScale})`,
                  transition: "none",
                }}
              >
                <span
                  style={{
                    color: accentColor,
                    fontSize: "72px",
                    fontWeight: 900,
                    lineHeight: 1,
                  }}
                >
                  {index + 1}
                </span>
              </div>

              {/* Blurred Content */}
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: "12px",
                  filter: `blur(${contentBlur}px)`,
                  opacity: contentOpacity,
                  transition: "none",
                }}
              >
                <h3
                  style={{
                    color: mainTitleColor,
                    fontSize: "48px",
                    fontWeight: 700,
                    margin: 0,
                  }}
                >
                  {step.title}
                </h3>
                <p
                  style={{
                    color: textColor,
                    fontSize: "32px",
                    lineHeight: 1.4,
                    margin: 0,
                    fontWeight: 400,
                  }}
                >
                  {step.description}
                </p>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default StepsAnimation;